<?php
session_start();
$isGradeSubmission = ($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && (string)($_GET['aksi'] ?? '') === 'simpan_nilai';
require_once __DIR__ . '/auth_guard.php';
app_require_authenticated_user($isGradeSubmission);
header('Cache-Control: private, no-store, max-age=0');
require_once 'koneksi.php';
if (!isset($koneksi) && isset($conn)) { $koneksi = $conn; }

$daftar_prodi = [
    'Pendidikan Teknologi Informasi',
    'Pendidikan Guru Sekolah Dasar',
    'Pendidikan Jasmani Kesehatan dan Rekreasi',
    'Pendidikan Bahasa dan Sastra Indonesia',
    'Pendidikan Sejarah',
    'Pendidikan Bahasa Inggris'
];
$allowed_themes = ['malam', 'putih', 'samudra', 'senja'];

// Endpoint JSON yang menerima nilai dari tombol "Simpan & Kirim" di rekap absen.
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_GET['aksi'] ?? '') === 'simpan_nilai') {
    header('Content-Type: application/json; charset=utf-8');
    $payload = json_decode(file_get_contents('php://input'), true);
    if (!is_array($payload)) {
        http_response_code(400);
        echo json_encode(['status' => 'error', 'msg' => 'Data nilai tidak terbaca.']);
        exit;
    }

    $prodi = trim((string)($payload['prodi'] ?? ''));
    $semester = trim((string)($payload['semester'] ?? ''));
    $kelas = strtoupper(trim((string)($payload['kelas'] ?? '')));
    if (!in_array($prodi, $daftar_prodi, true) || !ctype_digit($semester) || (int)$semester < 1 || (int)$semester > 8 || !in_array($kelas, ['A', 'B', 'C', 'D', 'E'], true)) {
        http_response_code(422);
        echo json_encode(['status' => 'error', 'msg' => 'Konteks prodi, semester, atau kelas tidak valid.']);
        exit;
    }

    $data_nilai = [];
    $incoming_rows = is_array($payload['data_nilai'] ?? null) ? $payload['data_nilai'] : [];
    foreach ($incoming_rows as $row) {
        if (!is_array($row)) continue;
        $nim = trim((string)($row['nim'] ?? ''));
        if ($nim === '') continue;
        $skor = is_numeric($row['skor_akhir'] ?? null) ? max(0, min(100, (float)$row['skor_akhir'])) : 0;
        $huruf = strtoupper(trim((string)($row['nilai_huruf'] ?? 'E')));
        if (!in_array($huruf, ['A', 'B', 'C', 'D', 'E'], true)) $huruf = 'E';
        $mutu = is_numeric($row['angka_mutu'] ?? null) ? max(0, min(4, (float)$row['angka_mutu'])) : 0;
        $potong_teks = static function ($teks, $maks) { return function_exists('mb_substr') ? mb_substr($teks, 0, $maks) : substr($teks, 0, $maks); };
        $data_nilai[] = [
            'nim' => $potong_teks($nim, 50),
            'nama' => $potong_teks(trim((string)($row['nama'] ?? '')), 255),
            'skor_akhir' => round($skor, 2),
            'nilai_huruf' => $huruf,
            'angka_mutu' => $mutu,
            'alpa' => max(0, (int)($row['alpa'] ?? 0))
        ];
    }

    $bobot = [];
    $incoming_bobot = is_array($payload['bobot'] ?? null) ? $payload['bobot'] : [];
    foreach (['absensi', 'aktivitas', 'uts', 'uas'] as $kunci) {
        $bobot[$kunci] = is_numeric($incoming_bobot[$kunci] ?? null) ? max(0, min(100, (float)$incoming_bobot[$kunci])) : 0;
    }
    $_SESSION['nilai_ujian'][$prodi][(string)(int)$semester][$kelas] = [
        'data_nilai' => $data_nilai,
        'bobot' => $bobot,
        'saved_at' => date('Y-m-d H:i:s')
    ];
    try { wa_db()->begin_transaction(); wa_save_document(['jenjang'=>'S1','prodi'=>$prodi,'semester'=>$semester,'kelas'=>$kelas],wa_text($payload['matkul']??'',180),'grade',$_SESSION['nilai_ujian'][$prodi][(string)(int)$semester][$kelas],null); wa_db()->commit(); } catch(Throwable $error) { wa_db()->rollback(); http_response_code(503); echo json_encode(['status'=>'error','msg'=>'Nilai belum tersimpan permanen. Coba lagi.']); exit; }
    $_SESSION['konteks_siswa'] = ['jenjang' => 'S1', 'kelas' => $kelas, 'prodi' => $prodi, 'semester' => (string)(int)$semester];
    echo json_encode(['status' => 'success', 'jumlah' => count($data_nilai), 'saved_at' => date('d-m-Y H:i')], JSON_UNESCAPED_UNICODE);
    exit;
}

$requested_theme = trim((string)($_GET['theme'] ?? ''));
if ($requested_theme !== '' && in_array($requested_theme, $allowed_themes, true)) $_SESSION['theme'] = $requested_theme;
$theme = $_SESSION['theme'] ?? 'malam';
if (!in_array($theme, $allowed_themes, true)) $theme = 'malam';

$saved_context = $_SESSION['konteks_siswa'] ?? [];
$jenjang = 'S1';
$prodi = trim((string)($_GET['prodi'] ?? $saved_context['prodi'] ?? $daftar_prodi[0]));
if (!in_array($prodi, $daftar_prodi, true)) $prodi = $daftar_prodi[0];
$kelas = strtoupper(trim((string)($_GET['kelas'] ?? $saved_context['kelas'] ?? 'A')));
$kelas = preg_replace('/^KELAS\s+/i', '', $kelas);
if (!in_array($kelas, ['A', 'B', 'C', 'D', 'E'], true)) $kelas = 'A';
$semester = trim((string)($_GET['semester'] ?? $saved_context['semester'] ?? '1'));
$semester = preg_replace('/^SEMESTER\s+/i', '', $semester);
if (!ctype_digit($semester) || (int)$semester < 1 || (int)$semester > 8) $semester = '1';
$semester = (string)(int)$semester;
$kelas_lama = 'Kelas ' . $kelas;
$semester_lama = 'Semester ' . $semester;
$_SESSION['konteks_siswa'] = ['jenjang' => 'S1', 'kelas' => $kelas, 'prodi' => $prodi, 'semester' => $semester];

$roman = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'];
$semesterLabel = $roman[(int)$semester] . ' ' . $kelas . (((int)$semester % 2) ? ' (Ganjil)' : ' (Genap)');
$tahun = (int)date('Y');
$tahunAjaran = ((int)date('n') >= 7) ? ($tahun . '/' . ($tahun + 1)) : (($tahun - 1) . '/' . $tahun);
$data_siswa = [];
$kelas_lama = 'Kelas ' . $kelas;
$semester_lama = 'Semester ' . $semester;
if (isset($koneksi) && $koneksi instanceof mysqli) {
    $sql = "SELECT nim, nama FROM siswa WHERE jenjang='S1' AND kelas IN (?, ?) AND prodi=? AND semester IN (?, ?) ORDER BY id ASC";
    $stmt = mysqli_prepare($koneksi, $sql);
    if ($stmt) {
        mysqli_stmt_bind_param($stmt, 'sssss', $kelas, $kelas_lama, $prodi, $semester, $semester_lama);
        mysqli_stmt_execute($stmt);
        $result = mysqli_stmt_get_result($stmt);
        if ($result) while ($row = mysqli_fetch_assoc($result)) $data_siswa[] = $row;
        mysqli_stmt_close($stmt);
    }
}
$saved_grade = $_SESSION['nilai_ujian'][$prodi][$semester][$kelas] ?? [];
if(!defined('APP_TEMPLATE_BUILD')){try{$stored=wa_document(['jenjang'=>'S1','prodi'=>$prodi,'semester'=>$semester,'kelas'=>$kelas],wa_text($_GET['matkul']??'',180),'grade');if($stored)$saved_grade=$stored['content'];}catch(Throwable $ignored){}}
$nilai_by_nim = [];
foreach (($saved_grade['data_nilai'] ?? []) as $nilai) {
    if (isset($nilai['nim'])) $nilai_by_nim[(string)$nilai['nim']] = $nilai;
}
$escape = static function ($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); };
$local_key = 'ujian_S1_' . md5($prodi . '|' . $semester . '|' . $kelas);
$logo_kiri_data = 'data:image/png;base64,';
$logo_kanan_data = 'data:image/png;base64,';
?>
