        function cetakLembarUjian() {
            const ua=navigator.userAgent||'';
            const webview=/android/i.test(ua)&&(/\bwv\b|; wv\)/i.test(ua)||!navigator.share);
            if(webview){
                const bridge=window.Android||window.AndroidInterface;
                if(typeof bridge?.printDocument==='function'){bridge.printDocument(window.AbsensiNativeExport?.html?.()||document.documentElement.outerHTML,location.href);return;}
                if(typeof bridge?.printPage==='function'){bridge.printPage();return;}
                if(typeof bridge?.print==='function'){bridge.print();return;}
                document.getElementById('bantuanAndroidCetak')?.remove();
                const overlay=document.createElement('div');overlay.id='bantuanAndroidCetak';
                overlay.style.cssText='position:fixed;inset:0;z-index:1000000;background:#0009;display:grid;place-items:center;padding:16px;font:16px Arial,sans-serif';
                overlay.innerHTML='<section style="max-width:440px;width:100%;background:#fff;color:#172033;border-radius:14px;padding:20px;box-shadow:0 16px 48px #0005"><h2 style="margin:0 0 10px;font-size:19px">Cetak dari aplikasi Android</h2><p style="line-height:1.5;margin:0 0 16px">Aplikasi ini belum meneruskan perintah cetak ke Android. Buka halaman yang sama di Chrome, lalu pilih Cetak atau Simpan sebagai PDF dari menu cetak.</p><button type="button" data-open-browser style="min-height:44px;padding:10px 14px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:bold">Buka halaman di Chrome</button> <button type="button" data-close style="min-height:44px;padding:10px 14px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#172033">Tutup</button></section>';
                overlay.addEventListener('click',event=>{
                    if(event.target===overlay||event.target.closest('[data-close]'))overlay.remove();
                    if(event.target.closest('[data-open-browser]')){
                        const intent='intent://'+location.href.replace(/^https?:\/\//i,'')+'#Intent;scheme=https;package=com.android.chrome;end';
                        const link=document.createElement('a');link.href=intent;link.target='_system';link.rel='noopener';document.body.appendChild(link);link.click();link.remove();overlay.remove();
                    }
                });document.body.appendChild(overlay);return;
            }
            window.print();
        }
        function escapeHtmlUjian(value) {
            const span=document.createElement('span');span.textContent=String(value??'');return span.innerHTML;
        }
        function cloneTabelUjian(selector) {
            window.WAFitSheetText?.();
            const source=paper.querySelector(selector);
            if(!source)return '';
            const table=source.cloneNode(true);
            table.querySelectorAll('.page-preview-only').forEach(el=>el.remove());
            table.removeAttribute('id');table.removeAttribute('onclick');table.removeAttribute('aria-label');
            table.style.cssText='width:100%;border-collapse:collapse;table-layout:fixed;margin:0;';
            table.querySelectorAll('[contenteditable]').forEach(el=>el.removeAttribute('contenteditable'));
            table.querySelectorAll('[data-edit-key]').forEach(el=>el.removeAttribute('data-edit-key'));
            table.querySelectorAll('th,td').forEach(cell=>{
                cell.style.border='1px solid #111';cell.style.padding='3px 6px';cell.style.verticalAlign='middle';cell.style.color='#111';
                const fitted=parseFloat(cell.style.fontSize);cell.style.fontSize=Number.isFinite(fitted)?Math.min(fitted,selector==='#examTableBlock table'?10.66:10)+'px':selector==='#examTableBlock table'?'8pt':'7.5pt';cell.style.whiteSpace='nowrap';cell.style.overflowWrap='normal';
                if(cell.tagName==='TH'){cell.style.textAlign='center';cell.style.fontWeight='bold';cell.style.backgroundColor='#e2e8f0';}
                else if(cell.classList.contains('name'))cell.style.textAlign='left';
                else cell.style.textAlign='center';
            });
            return table.outerHTML;
        }
        function markupLogoUjian(id) {
            const img=paper.querySelector(`#${id} img`);
            if(!img||img.hidden||!img.getAttribute('src'))return '';
            return `<img src="${escapeHtmlUjian(img.getAttribute('src'))}" width="64" height="64" alt="${escapeHtmlUjian(img.alt)}" style="width:64px;height:64px;object-fit:contain;display:block;margin:auto">`;
        }
        function markupHeaderUjian() {
            const lines=[...paper.querySelectorAll('#examInstitution .line, #examInstitution .contact')];
            const text=lines.map((line,index)=>`<div style="${line.classList.contains('contact')?'font-size:8pt;font-style:italic;margin-top:2px;':'font-size:'+(index===0?'10pt':'12pt')+';font-weight:bold;text-transform:uppercase;'}line-height:1.2">${escapeHtmlUjian(line.textContent.trim())}</div>`).join('');
            return `<table class="export-header" style="width:100%;border:0;border-collapse:collapse;table-layout:fixed;margin:0 0 5px"><tr><td style="width:14%;border:0;text-align:center;vertical-align:middle">${markupLogoUjian('logoLeftSlot')}</td><td style="width:72%;border:0;text-align:center;vertical-align:middle">${text}</td><td style="width:14%;border:0;text-align:center;vertical-align:middle">${markupLogoUjian('logoRightSlot')}</td></tr></table><div style="border-top:3px double #111;margin:4px 0 7px"></div>`;
