        function markupMetaUjian() {
            const columns=['#examMetaLeft','#examMetaRight'].map(selector=>[...paper.querySelectorAll(`${selector} .meta-row`)].map(row=>({
                label:row.querySelector('.meta-label')?.textContent.trim()||'',value:row.querySelector('.meta-value')?.textContent.trim()||'',font:Math.min(10.66,parseFloat(getComputedStyle(row.querySelector('.meta-value')).fontSize))
            })));
            const count=Math.max(...columns.map(rows=>rows.length));
            const rows=Array.from({length:count},(_,index)=>{
                const cells=columns.flatMap(column=>{
                    const item=column[index]||{label:'',value:''};
                    return [`<td style="width:20%;border:0;padding:2px 2px 2px 0;white-space:nowrap;font-weight:bold;text-transform:uppercase">${escapeHtmlUjian(item.label)}</td>`,`<td style="width:2%;border:0;padding:2px 0;text-align:center">${item.label?':':''}</td>`,`<td style="width:28%;border:0;padding:2px 5px 2px 0;vertical-align:top;white-space:nowrap;font-size:${item.font||10.66}px">${escapeHtmlUjian(item.value)}</td>`];
                }).join('');
                return `<tr>${cells}</tr>`;
            }).join('');
            return `<table class="export-meta" style="width:100%;border:0;border-collapse:collapse;table-layout:fixed;margin:0 0 8px;font:8pt 'Times New Roman',serif">${rows}</table>`;
        }
        function markupTandaTanganUjian(id) {
