            const markup = `<!doctype html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"><meta http-equiv="Content-Type" content="text/html; charset=utf-8"><meta name="ProgId" content="${excel?'Excel.Sheet':'Word.Document'}"><title>${titleAttr}</title>${excel?`<!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Lembar Ujian</x:Name><x:WorksheetOptions><x:DisplayGridlines>True</x:DisplayGridlines><x:FitToPage>True</x:FitToPage></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->`:''}<style>${styles}${excel?'body{font-family:Arial,sans-serif}td,th{mso-number-format:"\\@"}':''}</style></head><body><div id="exportRoot">${body}</div></body></html>`;
            return window.WAFitExportHTML?.(markup,186*96/25.4)||markup;
