        function simpanBerkasUjian(content,mime,filename) {
            const blob=new Blob(['\ufeff',content],{type:mime}),ua=navigator.userAgent||'',androidWebView=/android/i.test(ua)&&(/\bwv\b|; wv\)/i.test(ua)||!navigator.share);
            if(androidWebView){
                const bridge=window.Android||window.AndroidInterface;
                if(typeof bridge?.saveFile==='function'){const reader=new FileReader();reader.onload=()=>bridge.saveFile(filename,mime,String(reader.result).split(',')[1]);reader.readAsDataURL(blob);return;}
                if(typeof File==='function'&&navigator.share&&navigator.canShare){const file=new File([blob],filename,{type:mime.split(';')[0]});if(navigator.canShare({files:[file]})){navigator.share({files:[file],title:filename}).catch(error=>{if(error?.name!=='AbortError')alert('Berkas tidak dapat dibagikan. Buka halaman di Chrome untuk mengunduhnya.');});return;}}
                alert('Aplikasi belum mengaktifkan fitur simpan berkas. Buka halaman ini di Chrome, lalu pilih Word atau Excel kembali.');return;
            }
            const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
        }
        function eksporWordUjian(){
            const name='Lembar_Ujian_S1_Kelas_<?php echo htmlspecialchars(preg_replace('/[^A-Za-z0-9_-]+/', '_', $kelas), ENT_QUOTES); ?>_Semester_<?php echo htmlspecialchars(preg_replace('/[^A-Za-z0-9_-]+/', '_', $semester), ENT_QUOTES); ?>.doc';
            simpanBerkasUjian(dokumenPenuhUjian('word'),'application/msword;charset=utf-8',name);
        }
        function eksporExcelUjian(){
            const name='Lembar_Ujian_S1_Kelas_<?php echo htmlspecialchars(preg_replace('/[^A-Za-z0-9_-]+/', '_', $kelas), ENT_QUOTES); ?>_Semester_<?php echo htmlspecialchars(preg_replace('/[^A-Za-z0-9_-]+/', '_', $semester), ENT_QUOTES); ?>.xls';
            simpanBerkasUjian(dokumenPenuhUjian('excel'),'application/vnd.ms-excel;charset=utf-8',name);
        }
        function toggleToolbar() {
            document.getElementById('topToolbar').classList.toggle('hidden-toolbar');
            sinkronkanPeganganPanel();
        }
        function toggleInspectorPanel() {
            document.getElementById('inspectorPanel').classList.toggle('minimized');
            sinkronkanPeganganPanel();
        }
        function sinkronkanPeganganPanel() {
            const toolbar=document.getElementById('topToolbar'),panel=document.getElementById('inspectorPanel'),menuButton=document.getElementById('toggleToolbarBtn'),panelButton=document.getElementById('inspectorToggleBtn');
            const menuHidden=toolbar.classList.contains('hidden-toolbar'),panelHidden=panel.classList.contains('minimized');
            toolbar.inert=menuHidden;panel.inert=panelHidden;
            menuButton.textContent=menuHidden?'⌄ Menu':'⌃ Menu';
            menuButton.title=menuHidden?'Tampilkan menu atas':'Menu atas sedang tampil';
            menuButton.classList.toggle('show',menuHidden);
            menuButton.setAttribute('aria-expanded',String(!menuHidden));menuButton.setAttribute('aria-label',menuButton.title);
            panelButton.classList.toggle('show',panelHidden);panelButton.setAttribute('aria-expanded',String(!panelHidden));
        }
        function pasangUsapanPanel(element,axis,hide) {
            let start=null;
            element.addEventListener('touchstart',event=>{
                if(event.touches.length!==1||event.target.closest('input,textarea,select,[contenteditable="true"]')){start=null;return;}
                const touch=event.touches[0];start={x:touch.clientX,y:touch.clientY,time:Date.now()};
            },{passive:true});
            element.addEventListener('touchend',event=>{
                if(!start||!event.changedTouches.length)return;
                const touch=event.changedTouches[0],dx=touch.clientX-start.x,dy=touch.clientY-start.y,elapsed=Date.now()-start.time;start=null;
                if(typeof tourActive!=='undefined'&&tourActive)return;
                if(elapsed>1200)return;
                if((axis==='up'&&dy< -44&&Math.abs(dy)>Math.abs(dx)*1.35)||(axis==='right'&&dx>44&&dx>Math.abs(dy)*1.35))hide();
            },{passive:true});
            element.addEventListener('touchcancel',()=>{start=null;},{passive:true});
        }
        const menuPanel=document.getElementById('topToolbar'),layoutPanel=document.getElementById('inspectorPanel');
        pasangUsapanPanel(menuPanel,'up',()=>{menuPanel.classList.add('hidden-toolbar');sinkronkanPeganganPanel();});
        pasangUsapanPanel(layoutPanel,'right',()=>{layoutPanel.classList.add('minimized');sinkronkanPeganganPanel();});
        const panelObserver=new MutationObserver(sinkronkanPeganganPanel);
        [menuPanel,layoutPanel].forEach(el=>panelObserver.observe(el,{attributes:true,attributeFilter:['class']}));
        new ResizeObserver(sinkronkanPeganganPanel).observe(menuPanel);
        window.addEventListener('resize',sinkronkanPeganganPanel);
        sinkronkanPeganganPanel();
        function updateZoom() {
            paper.style.zoom = String(zoomLevel);
            document.getElementById('zoomLabel').textContent = Math.round(zoomLevel * 100) + '%';
        }
        function ubahZoom(delta) { zoomLevel = Math.max(.6, Math.min(1.6, Math.round((zoomLevel + delta) * 10) / 10)); updateZoom(); }
        function resetZoom() { zoomLevel = 1; updateZoom(); }

        function readSavedEdits() {
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}') || {};
                if (saved.blankCourseVersion !== 1) {
                    saved.text = saved.text || {};
                    if (/^(Profesi Kependidikan|Pengembangan Pembelajaran Interaktif)$/.test(String(saved.text['course-label'] || '').trim())) saved.text['course-label'] = '';
                    saved.blankCourseVersion = 1;
                    try { localStorage.setItem(storageKey, JSON.stringify(saved)); } catch (error) {}
                }
                // Kosongkan dua jawaban lama sekali saja, sesuai format baru.
                // Jawaban yang kemudian diketik dosen tetap tersimpan.
                if (saved.blankExamFieldsVersion !== 2) {
                    saved.text = saved.text || {};
                    saved.text['room-label'] = '';
                    saved.text['time-label'] = '';
                    saved.blankExamFieldsVersion = 2;
                    try { localStorage.setItem(storageKey, JSON.stringify(saved)); } catch (error) {}
                }
                document.querySelectorAll('[data-edit-key]').forEach(el => {
                    const key = el.dataset.editKey;
                    if (Object.prototype.hasOwnProperty.call(saved.text || {}, key)) {
                        let text = String(saved.text[key] ?? '');
                        // Hilangkan isian garis bawaan lama, sambil mempertahankan jawaban yang diketik dosen.
                        if (key === 'room-label' && /^(?:(?:KELAS\s+)?[A-E]\s*\/\s*)?_+$/i.test(text.trim())) text = '';
                        if (key === 'time-label' && /^_+$/.test(text.trim())) text = '';
                        el.textContent = text;
                    }
                });
                ['logoLeftSlot', 'logoRightSlot'].forEach(id => { if (saved.logos && saved.logos[id]) setLogo(id, saved.logos[id]); });
                Object.entries(saved.positions || {}).forEach(([id, transform]) => { const el = document.getElementById(id); if (el && el.matches('.selectable-element')) el.style.transform = transform; });
                Object.entries(saved.paragraphSpacing || {}).forEach(([id, setting]) => {
                    const el = document.getElementById(id);
                    if (el && el.matches('.selectable-element')) terapkanSpasiParagrafUjian(el, setting);
                });
            } catch (error) { console.warn('Pengaturan lembar ujian lokal tidak dapat dibaca.', error); }
        }
        function saveEdits() {
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                saved.text = saved.text || {};
                document.querySelectorAll('[data-edit-key]').forEach(el => { saved.text[el.dataset.editKey] = el.textContent; });
                localStorage.setItem(storageKey, JSON.stringify(saved));
            } catch (error) { alert('Penyimpanan edit teks penuh. Hapus beberapa data situs dari pengaturan browser lalu coba lagi.'); }
        }
        function terapkanSpasiParagrafUjian(el, setting) {
            if (!el || !setting) return;
            el.style.lineHeight = String(setting.line || 1);
            el.style.marginTop = `${Number(setting.before) || 0}pt`;
            el.style.marginBottom = `${Number(setting.after) || 0}pt`;
        }
        function sinkronkanKontrolSpasiParagrafUjian() {
            const controls = ['examParagraphLineSpacing','examParagraphSpaceBefore','examParagraphSpaceAfter'].map(id => document.getElementById(id));
            controls.forEach(control => { if (control) control.disabled = !selectedElement; });
            if (!selectedElement) return;
            let saved = {};
            try { saved = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch (error) {}
            const setting = saved.paragraphSpacing?.[selectedElement.id] || {line:1,before:0,after:0};
            document.getElementById('examParagraphLineSpacing').value = String(setting.line || 1);
            document.getElementById('examParagraphSpaceBefore').value = String(Number(setting.before) || 0);
            document.getElementById('examParagraphSpaceAfter').value = String(Number(setting.after) || 0);
        }
        function aturSpasiParagrafUjian() {
            if (!selectedElement || !selectedElement.id) return;
            const setting = {
                line:Math.max(1,Math.min(3,Number(document.getElementById('examParagraphLineSpacing').value)||1)),
                before:Math.max(0,Math.min(72,Number(document.getElementById('examParagraphSpaceBefore').value)||0)),
                after:Math.max(0,Math.min(72,Number(document.getElementById('examParagraphSpaceAfter').value)||0))
            };
            terapkanSpasiParagrafUjian(selectedElement, setting);
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                saved.paragraphSpacing = saved.paragraphSpacing || {};
                saved.paragraphSpacing[selectedElement.id] = setting;
                localStorage.setItem(storageKey, JSON.stringify(saved));
            } catch (error) { console.warn('Pengaturan spasi paragraf belum tersimpan.', error); }
            perbaruiPenandaHalamanUjian();
        }
        function resetSpasiParagrafUjian() {
            if (!selectedElement) return;
            selectedElement.style.lineHeight = '';
            selectedElement.style.marginTop = '';
            selectedElement.style.marginBottom = '';
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                if (saved.paragraphSpacing) delete saved.paragraphSpacing[selectedElement.id];
                localStorage.setItem(storageKey, JSON.stringify(saved));
            } catch (error) {}
            sinkronkanKontrolSpasiParagrafUjian();
            perbaruiPenandaHalamanUjian();
        }
        function setLogo(slotId, src) {
            const slot = document.getElementById(slotId), img = slot.querySelector('img'), icon = slot.querySelector('i'), remove = slot.querySelector('.logo-remove');
            img.src = src; img.hidden = false; icon.hidden = true; remove.hidden = src === img.dataset.defaultSrc; slot.classList.add('has-logo');
        }
        function saveLogo(slotId, src) {
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                saved.logos = saved.logos || {}; saved.logos[slotId] = src;
                localStorage.setItem(storageKey, JSON.stringify(saved));
            } catch (error) { alert('Ukuran logo terlalu besar untuk disimpan di browser. Gunakan gambar yang lebih kecil.'); }
        }
        document.querySelectorAll('.logo-slot').forEach(slot => {
            const input = slot.querySelector('input[type="file"]');
            const remove = slot.querySelector('.logo-remove');
            const image = slot.querySelector('img'); image.dataset.defaultSrc = image.src;
            slot.classList.add('has-logo');
            input.addEventListener('change', event => {
                const file = event.target.files && event.target.files[0];
                if (!file) return;
                if (!file.type.startsWith('image/')) { alert('Pilih berkas gambar untuk logo.'); return; }
                const reader = new FileReader();
                reader.onload = () => { setLogo(slot.id, reader.result); saveLogo(slot.id, reader.result); };
                reader.readAsDataURL(file);
            });
            remove.addEventListener('click', event => {
                event.preventDefault(); event.stopPropagation();
                const image = slot.querySelector('img');
                if (image.dataset.defaultSrc) { setLogo(slot.id, image.dataset.defaultSrc); remove.hidden = true; }
                else { image.removeAttribute('src'); image.hidden = true; slot.querySelector('i').hidden = false; slot.classList.remove('has-logo'); }
                input.value = '';
                try { const saved = JSON.parse(localStorage.getItem(storageKey) || '{}'); if (saved.logos) delete saved.logos[slot.id]; localStorage.setItem(storageKey, JSON.stringify(saved)); } catch (error) {}
            });
        });
        function pilihElemen(event, el) {
            event.stopPropagation();
            document.querySelectorAll('.selectable-element.selected').forEach(node => node.classList.remove('selected'));
            selectedElement = el;
            el.classList.add('selected');
            el.tabIndex = 0;
            if (!event.target.closest('input,textarea,select,[contenteditable="true"]')) el.focus({preventScroll:true});
            document.getElementById('activeElementLabel').textContent = el.dataset.type || 'Elemen';
            sinkronkanKontrolSpasiParagrafUjian();
            const container = document.getElementById('inspectorTextContainer');
            container.replaceChildren();
            const editables = el.querySelectorAll('[contenteditable="true"]');
            if (!editables.length) { container.textContent = 'Elemen ini tidak memiliki teks yang dapat diedit.'; return; }
            editables.forEach((editable, index) => {
                const input = document.createElement('input');
                input.type = 'text'; input.value = editable.textContent; input.setAttribute('aria-label', 'Teks ' + (index + 1));
                input.addEventListener('input', () => { editable.textContent = input.value; saveEdits(); });
                container.appendChild(input);
            });
        }
        document.addEventListener('click', event => {
            if (!event.target.closest('.selectable-element') && !event.target.closest('.inspector-panel') && !event.target.closest('#toggleToolbarBtn,#inspectorToggleBtn,#topToolbar')) {
                document.querySelectorAll('.selectable-element.selected').forEach(node => node.classList.remove('selected'));
                selectedElement = null;
                document.getElementById('activeElementLabel').textContent = 'Pilih elemen di lembar kerja...';
                document.getElementById('inspectorTextContainer').innerHTML = '<div style="font-size:11px;color:var(--muted);">Klik blok pada lembar untuk mengedit teksnya di sini.</div>';
                sinkronkanKontrolSpasiParagrafUjian();
            }
        });
        function simpanPosisi() {
            const positions = {};
            document.querySelectorAll('.selectable-element[id]').forEach(el => { if (el.style.transform) positions[el.id] = el.style.transform; });
            try { const saved = JSON.parse(localStorage.getItem(storageKey) || '{}'); saved.positions = positions; localStorage.setItem(storageKey, JSON.stringify(saved)); } catch (error) {}
        }
        function ubahPosisiAktif(axis, delta) {
            if (!selectedElement) return;
            const readPosition = el => { const m = (el.style.transform || '').match(/translate\(\s*([-\d.]+)px\s*,\s*([-\d.]+)px\s*\)/); return m ? [parseFloat(m[1]), parseFloat(m[2])] : [0, 0]; };
            const moving = axis === 'y' ? [selectedElement, ...Array.from(selectedElement.parentElement.children).filter(el => {
                if (el === selectedElement || !el.matches('.selectable-element')) return false;
                const a = selectedElement.getBoundingClientRect(), b = el.getBoundingClientRect();
                const overlap = Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top));
                return b.width > 0 && b.height > 0 && overlap >= Math.min(a.height, b.height) * .45;
            })] : [selectedElement];
            moving.forEach(el => { let [x,y] = readPosition(el); if (axis === 'x') x += delta; else y += delta; el.style.transform = `translate(${x}px, ${y}px)`; });
            simpanPosisi();
        }
        function resetPosisiAktif() { if (selectedElement) { selectedElement.style.transform = 'translate(0px, 0px)'; simpanPosisi(); } }
        document.addEventListener('keydown', event => {
            if (tourActive) return;
            if (!selectedElement || !['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)) return;
            if (event.target.closest && event.target.closest('input,textarea,select,a')) return;
            event.preventDefault(); const step = event.shiftKey ? 5 : 1;
            if (event.key === 'ArrowUp') ubahPosisiAktif('y',-step);
            if (event.key === 'ArrowDown') ubahPosisiAktif('y',step);
            if (event.key === 'ArrowLeft') ubahPosisiAktif('x',-step);
            if (event.key === 'ArrowRight') ubahPosisiAktif('x',step);
        });
        document.addEventListener('input', event => { if (event.target.matches('[contenteditable="true"]')) saveEdits(); });
        readSavedEdits();
        sinkronkanKontrolSpasiParagrafUjian();
        updateZoom();
    </script>
</body>
</html>
